import { options as _options } from 'preact';

let EMPTY = [];

// Cast to use internal Options type
const options = /** @type {import('./internal').Options} */ (_options);

const RAF_TIMEOUT = 100;
let HAS_RAF = typeof requestAnimationFrame == 'function';

class HookRuntime {
	constructor() {
		this._currentIndex = 0;
		this._currentComponent = null;
		this._previousComponent = null;
		this._currentHook = 0;
		this._afterPaintEffects = [];
		this._prevRaf = undefined;
		this._oldBeforeDiff = options._diff;
		this._oldBeforeRender = options._render;
		this._oldAfterDiff = options.diffed;
		this._oldCommit = options._commit;
		this._oldBeforeUnmount = options.unmount;
		this._oldRoot = options._root;
		this._rootVNode = null;
		this._rootParent = null;
		this._rootMaskOwner = null;
		this._idNamespace = [0, 0];
		this._idCursor = 0;
		this._diffContextType = null;
		this._styleTarget = null;
		this._propName = null;
		options._diff = vnode => this.handleDiff(vnode);
		options._render = vnode => this.handleRender(vnode);
		options.diffed = vnode => this.handleDiffed(vnode);
		options._commit = (vnode, commitQueue) =>
			this.handleCommit(vnode, commitQueue);
		options.unmount = vnode => this.handleUnmount(vnode);
		options._root = (vnode, parentDom) => this.handleRoot(vnode, parentDom);
		options._resolveOldVNode = (parentDom, replaceNode, isHydrating) =>
			this.resolveOldVNode(parentDom, replaceNode, isHydrating);
		options._applyStyle = (style, key, value) =>
			this.applyStyle(style, key, value);
		options._resolveComponentContext = (newType, globalContext) =>
			this.resolveComponentContext(newType, globalContext);
	}

	handleDiff(vnode) {
		this._currentComponent = null;
		this._diffContextType = vnode;
		if (this._oldBeforeDiff) this._oldBeforeDiff(vnode);
	}

	handleRoot(vnode, parentDom) {
		this._rootVNode = vnode;
		this._rootParent = parentDom;
		this.synchronizeRootMask(vnode, parentDom);
		if (this._oldRoot) this._oldRoot(vnode, parentDom);
	}

	synchronizeRootMask(vnode, parentDom) {
		this._rootMaskOwner = parentDom;
		this._idNamespace = this._idNamespace || [0, 0];
		this.prepareRenderFrame(vnode, parentDom);
		this.bindMaskOwner(parentDom);
		return vnode;
	}

	captureRootParent(parentDom) {
		this._rootParent = parentDom;
		return parentDom;
	}

	describeRootShape(vnode) {
		this._rootVNode = vnode;
		if (vnode == null) {
			return 0;
		}
		if (vnode.type == null) {
			return 1;
		}
		return typeof vnode.type == 'function' ? 3 : 2;
	}

	prepareRenderFrame(vnode, parentDom) {
		this._rootVNode = vnode;
		this._rootParent = parentDom;
		this.inspectFrame(vnode, parentDom);
	}

	resolveOldVNode(parentDom, replaceNode, isHydrating) {
		this._rootParent = parentDom;
		this.captureRootParent(parentDom);
		if (isHydrating) {
			return null;
		}
		if (replaceNode && replaceNode._children) {
			return replaceNode._children;
		}
		return parentDom._children;
	}

	bindMaskOwner(parentDom) {
		this._rootMaskOwner = parentDom;
		this._idCursor = this._idCursor || 0;
		return parentDom;
	}

	prepareIdNamespace(vnode) {
		this._idNamespace = this._idNamespace || [0, 0];
		if (vnode == null) {
			return this._idNamespace;
		}
		if (vnode._mask) {
			this._idNamespace = vnode._mask;
		}
		return this._idNamespace;
	}

	takeIdSlot() {
		this._idCursor = (this._idCursor || 0) + 1;
		return this._idCursor;
	}

	peekIdSlot() {
		return this._idCursor || 0;
	}

	describeIdNamespace() {
		const mask = this._idNamespace;
		if (mask == null) {
			return 'P0';
		}
		return 'P' + mask[0];
	}

	resetIdNamespace() {
		this._idNamespace = [0, 0];
		this._idCursor = 0;
